class Solution {
  public int[] maxValue(int[] nums) {
    int n = nums.length;
    int[] prefixMax = new int[n];
    prefixMax[0] = nums[0];
    for (int i = 1; i < n; i++) prefixMax[i] = Math.max(prefixMax[i - 1], nums[i]);
    int[] ans = new int[n];
    ans[n - 1] = prefixMax[n - 1];
    int suffixMin = nums[n - 1];
    for (int i = n - 2; i >= 0; i--) {
      // the left part can reach the right part iff its maximum exceeds the right part's minimum
      ans[i] = prefixMax[i] > suffixMin ? ans[i + 1] : prefixMax[i];
      suffixMin = Math.min(suffixMin, nums[i]);
    }
    return ans;
  }
}
